-- ==============================================================================
-- IMMEDIATE DATABASE ROLLBACK & RESTORATION SCRIPT
-- ==============================================================================
-- 1. Drops the auto-scoring trigger & function.
-- 2. Restores the exact pre-migration length_words, cost_raw, cost,
--    difficulty_score, and difficulty for all unvalidated sentences.
-- 3. Restores exact counts: 6,424 easy | 6,424 medium | 3,213 hard.
-- 4. Preserves all validated sentences, claims, and payouts intact.
-- ==============================================================================

BEGIN;

DROP TRIGGER IF EXISTS trigger_auto_score_sentence ON sentences;
DROP FUNCTION IF EXISTS calculate_sentence_scoring();

CREATE TEMP TABLE restore_sentence_data (
    source_row integer PRIMARY KEY,
    length_words integer,
    cost_raw numeric(8,4),
    cost numeric(5,4),
    difficulty_score numeric(5,4),
    difficulty text
) ON COMMIT DROP;

