-- Update sentences back to original pre-migration values
UPDATE sentences s
   SET length_words     = r.length_words,
       cost_raw         = r.cost_raw,
       cost             = r.cost,
       difficulty_score = r.difficulty_score,
       difficulty       = r.difficulty
  FROM restore_sentence_data r
 WHERE s.source_row = r.source_row
   AND s.validated_by IS NULL;

COMMIT;
